/* ============================ RISK MANAGER ============================== */

function computeRiskStatus(trades, riskLimits, currentBalance) {
  const today = todayStr();
  const closedToday = trades.filter((t) => t.status === "Closed" && (t.exitDate || "").slice(0, 10) === today);
  const openedToday = trades.filter((t) => (t.entryDate || t.createdAt || "").slice(0, 10) === today);
  const lossToday = closedToday.filter((t) => t.pnl < 0).reduce((s, t) => s + Math.abs(t.pnl), 0);
  const lossTodayPct = currentBalance ? (lossToday / currentBalance) * 100 : 0;

  const closedSorted = [...trades]
    .filter((t) => t.status === "Closed")
    .sort((a, b) => new Date(b.exitDate || b.createdAt) - new Date(a.exitDate || a.createdAt));
  let consecutiveLoss = 0;
  for (const t of closedSorted) {
    if (t.result === "Loss") consecutiveLoss += 1;
    else break;
  }

  const warnings = [];
  if (riskLimits.dailyTradeLimit && openedToday.length >= Number(riskLimits.dailyTradeLimit)) {
    warnings.push(`Daily trade limit reached (${openedToday.length}/${riskLimits.dailyTradeLimit}).`);
  }
  if (riskLimits.maxDailyLossAmount && lossToday >= Number(riskLimits.maxDailyLossAmount)) {
    warnings.push(`Daily loss amount limit reached.`);
  }
  if (riskLimits.maxDailyLossPercent && lossTodayPct >= Number(riskLimits.maxDailyLossPercent)) {
    warnings.push(`Daily risk limit reached (${lossTodayPct.toFixed(1)}%).`);
  }
  if (riskLimits.maxConsecutiveLoss && consecutiveLoss >= Number(riskLimits.maxConsecutiveLoss)) {
    warnings.push(`Max consecutive loss reached (${consecutiveLoss}x).`);
  }

  // Overtrading: same symbol opened too many times today
  const symbolCounts = {};
  openedToday.forEach((t) => {
    symbolCounts[t.symbol] = (symbolCounts[t.symbol] || 0) + 1;
  });
  const overtradedSymbol = Object.entries(symbolCounts).find(([, count]) => count >= 4);
  if (overtradedSymbol) {
    warnings.push(`Overtrading terdeteksi di ${overtradedSymbol[0]} (${overtradedSymbol[1]}x hari ini) — pertimbangkan untuk berhenti sejenak.`);
  }

  // Revenge trading: risk size increased right after 2+ consecutive losses
  if (consecutiveLoss >= 2) {
    const capPct = Number(riskLimits.maxRiskPerTradePercent) || null;
    const openTradesToday = trades.filter(
      (t) => t.status === "Open" && (t.entryDate || t.createdAt || "").slice(0, 10) === today
    );
    const oversizedAfterLoss = capPct
      ? openTradesToday.find((t) => Number(t.riskPercent) > capPct)
      : null;
    if (oversizedAfterLoss) {
      warnings.push(
        `Kemungkinan revenge trading — ukuran risiko trade ${oversizedAfterLoss.symbol} lebih besar dari batas normal setelah ${consecutiveLoss}x loss beruntun.`
      );
    }
  }

  return { warnings, lossToday, lossTodayPct, consecutiveLoss, tradesToday: openedToday.length };
}

