/* ============================ DASHBOARD ============================== */

function computeStreaks(closedSortedAsc) {
  // closedSortedAsc: closed trades sorted oldest -> newest
  let current = 0;
  let currentType = null;
  let bestWin = 0;
  let worstLoss = 0;
  let runWin = 0;
  let runLoss = 0;
  closedSortedAsc.forEach((t) => {
    if (t.result === "Win") {
      runWin += 1;
      runLoss = 0;
      bestWin = Math.max(bestWin, runWin);
    } else if (t.result === "Loss") {
      runLoss += 1;
      runWin = 0;
      worstLoss = Math.max(worstLoss, runLoss);
    } else {
      runWin = 0;
      runLoss = 0;
    }
  });
  // current streak = trailing run at the end
  for (let i = closedSortedAsc.length - 1; i >= 0; i--) {
    const t = closedSortedAsc[i];
    if (i === closedSortedAsc.length - 1) {
      currentType = t.result;
    }
    if (t.result === currentType && (currentType === "Win" || currentType === "Loss")) {
      current += 1;
    } else {
      break;
    }
  }
  return { current, currentType, bestWin, worstLoss };
}

function computeMetrics(trades, settings) {
  const closed = trades.filter((t) => t.status === "Closed");
  const closedAsc = [...closed].sort((a, b) => new Date(a.exitDate || a.createdAt) - new Date(b.exitDate || b.createdAt));
  const wins = closed.filter((t) => t.result === "Win");
  const losses = closed.filter((t) => t.result === "Loss");
  const totalPnl = closed.reduce((s, t) => s + (Number(t.pnl) || 0), 0);
  const initialBalance = Number(settings.startingBalance) || 0;
  const currentBalance = initialBalance + totalPnl;
  const winRate = closed.length ? (wins.length / closed.length) * 100 : 0;
  const lossRate = closed.length ? (losses.length / closed.length) * 100 : 0;
  const avgWin = wins.length ? wins.reduce((s, t) => s + t.pnl, 0) / wins.length : 0;
  const avgLoss = losses.length ? losses.reduce((s, t) => s + t.pnl, 0) / losses.length : 0;
  const grossWin = wins.reduce((s, t) => s + t.pnl, 0);
  const grossLoss = Math.abs(losses.reduce((s, t) => s + t.pnl, 0));
  const profitFactor = grossLoss ? grossWin / grossLoss : grossWin > 0 ? Infinity : 0;
  const expectancy = closed.length ? (winRate / 100) * avgWin + (lossRate / 100) * avgLoss : 0;
  const rValues = closed.filter((t) => t.rMultiple != null && isFinite(t.rMultiple)).map((t) => t.rMultiple);
  const avgRR = rValues.length ? rValues.reduce((a, b) => a + b, 0) / rValues.length : 0;

  // equity curve + drawdown
  let running = initialBalance;
  let peak = initialBalance;
  let maxDD = 0;
  const equityPoints = [];
  closedAsc.forEach((t) => {
    running += t.pnl;
    peak = Math.max(peak, running);
    maxDD = Math.max(maxDD, peak - running);
    equityPoints.push({
      date: fmtDateOnly(t.exitDate || t.createdAt),
      rawDate: t.exitDate || t.createdAt,
      balance: running,
      pnl: t.pnl,
    });
  });
  const maxDDPercent = peak ? (maxDD / peak) * 100 : 0;

  const today = todayStr();
  const todayPnl = closed.filter((t) => (t.exitDate || "").slice(0, 10) === today).reduce((s, t) => s + t.pnl, 0);
  const weekPnl = closed
    .filter((t) => new Date(t.exitDate || t.createdAt) >= daysAgo(7))
    .reduce((s, t) => s + t.pnl, 0);
  const monthPnl = closed
    .filter((t) => new Date(t.exitDate || t.createdAt) >= daysAgo(30))
    .reduce((s, t) => s + t.pnl, 0);
  const now = new Date();
  const mtdPnl = closed
    .filter((t) => {
      const d = new Date(t.exitDate || t.createdAt);
      return d.getFullYear() === now.getFullYear() && d.getMonth() === now.getMonth();
    })
    .reduce((s, t) => s + t.pnl, 0);

  const returnPct = initialBalance ? (totalPnl / initialBalance) * 100 : 0;
  const streaks = computeStreaks(closedAsc);
  const openTrades = trades.filter((t) => t.status === "Open");

  return {
    closed,
    wins,
    losses,
    totalPnl,
    initialBalance,
    currentBalance,
    equity: currentBalance,
    winRate,
    lossRate,
    avgWin,
    avgLoss,
    profitFactor,
    expectancy,
    avgRR,
    maxDD,
    maxDDPercent,
    equityPoints,
    todayPnl,
    weekPnl,
    monthPnl,
    mtdPnl,
    returnPct,
    streaks,
    openTrades,
  };
}

function CountdownDisplay({ target }) {
  const [, setTick] = useState(0);
  useEffect(() => {
    const t = setInterval(() => setTick((x) => x + 1), 1000);
    return () => clearInterval(t);
  }, []);
  const parts = countdownParts(target);
  if (!parts) return <span>Sekarang</span>;
  return (
    <span>
      {parts.d > 0 && `${parts.d}h `}
      {String(parts.h).padStart(2, "0")}:{String(parts.m).padStart(2, "0")}:{String(parts.s).padStart(2, "0")}
    </span>
  );
}

