const HISTORY_FILTERS = ["All", "Open", "Win", "Loss", "BE", "Buy", "Sell"];

function TradeHistory({ trades, currency, onOpen, onClose, onDelete, onQuickWin, onQuickLose, onEdit }) {
  const [filter, setFilter] = useState("All");
  const [search, setSearch] = useState("");

  const filtered = useMemo(() => {
    return trades.filter((t) => {
      if (filter === "Open" && t.status !== "Open") return false;
      if (filter === "Win" && t.result !== "Win") return false;
      if (filter === "Loss" && t.result !== "Loss") return false;
      if (filter === "BE" && t.result !== "BE") return false;
      if (filter === "Buy" && t.direction !== "Buy") return false;
      if (filter === "Sell" && t.direction !== "Sell") return false;
      if (search && !`${t.symbol} ${t.strategy} ${t.session}`.toLowerCase().includes(search.toLowerCase())) return false;
      return true;
    });
  }, [trades, filter, search]);

  return (
    <div>
      <div
        style={{
          backgroundImage: `linear-gradient(rgba(5,6,7,0.55), rgba(5,6,7,0.82)), url(${HISTORY_BG})`,
          backgroundSize: "cover",
          backgroundPosition: "center",
          borderRadius: 16,
          padding: 14,
          boxShadow: "0 8px 24px rgba(0,0,0,0.45)",
        }}
      >
        <div style={{ display: "flex", gap: 8, alignItems: "center", marginBottom: 10, flexWrap: "wrap" }}>
          <div style={{ position: "relative", flex: "1 1 160px" }}>
            <Search size={14} color={COLORS.textFaint} style={{ position: "absolute", left: 10, top: 10 }} />
            <input
              value={search}
              onChange={(e) => setSearch(e.target.value)}
              placeholder="Cari symbol / strategy…"
              style={{ ...inputStyle, paddingLeft: 30, fontFamily: "'Inter', sans-serif" }}
            />
          </div>
        </div>
        <div style={{ display: "flex", gap: 6, marginBottom: 12, overflowX: "auto", paddingBottom: 2 }}>
          {HISTORY_FILTERS.map((f) => (
            <Pill key={f} active={filter === f} onClick={() => setFilter(f)}>
              {f}
            </Pill>
          ))}
        </div>

        {filtered.length === 0 ? (
          <EmptyState
            icon={NotebookPen}
            title="No trades yet"
            subtitle="Start your trading journal by recording your first trade."
          />
        ) : (
          filtered.map((t) => (
            <TradeCard
              key={t.id}
              trade={t}
              currency={currency}
              onOpen={onOpen}
              onClose={onClose}
              onDelete={onDelete}
              onQuickWin={onQuickWin}
              onQuickLose={onQuickLose}
              onEdit={onEdit}
            />
          ))
        )}
      </div>
    </div>
  );
}

