const DEFAULT_SETTINGS = {
  currency: "IDR",
  startingBalance: 10000000,
  defaultSymbol: "XAUUSD",
  defaultTimeframe: "M15",
  defaultRiskPercent: 1,
  defaultPointValue: 100,
  soundEnabled: true,
  monthlyProfitTarget: 0,
};

const DEFAULT_RISK = {
  maxRiskPerTradePercent: 2,
  maxDailyLossPercent: 5,
  maxDailyLossAmount: "",
  maxConsecutiveLoss: 3,
  dailyTradeLimit: 7,
};

const DEFAULT_PROFILE = {
  name: "Trader",
  photo: DEFAULT_AVATAR,
  accountType: "Real",
  accountTier: "Premium",
};

function downloadFile(filename, content, mime) {
  const blob = new Blob([content], { type: mime });
  const url = URL.createObjectURL(blob);
  const a = document.createElement("a");
  a.href = url;
  a.download = filename;
  document.body.appendChild(a);
  a.click();
  document.body.removeChild(a);
  URL.revokeObjectURL(url);
}

function tradesToCSV(trades) {
  const cols = ["date", "symbol", "direction", "entry", "exit", "sl", "tp", "lot", "pnl", "r", "result", "status"];
  const rows = trades.map((t) => [
    t.exitDate || t.entryDate || t.createdAt,
    t.symbol,
    t.direction,
    t.entryPrice,
    t.exitPrice ?? "",
    t.stopLoss ?? "",
    t.takeProfit ?? "",
    t.lot,
    t.pnl ?? "",
    t.rMultiple != null ? t.rMultiple.toFixed(2) : "",
    t.result ?? "",
    t.status,
  ]);
  return [cols.join(","), ...rows.map((r) => r.map((v) => `"${String(v ?? "").replace(/"/g, '""')}"`).join(","))].join("\n");
}

export default function Gtrade() {
  const [loaded, setLoaded] = useState(false);
  const [activeTab, setActiveTab] = useState("dashboard");
  const [settings, setSettings] = useState(DEFAULT_SETTINGS);
  const [riskLimits, setRiskLimits] = useState(DEFAULT_RISK);
  const [profile, setProfile] = useState(DEFAULT_PROFILE);
  const [trades, setTrades] = useState([]);
  const [chartRange, setChartRange] = useState("All");
  const [modalTrade, setModalTrade] = useState(null);
  const [modalMode, setModalMode] = useState("view");
  const [resultPopup, setResultPopup] = useState(null);
  const [resultReason, setResultReason] = useState(null);
  const [showResetConfirm, setShowResetConfirm] = useState(false);
  const [monitorOn, setMonitorOn] = useState(true);
  const [monitorStatus, setMonitorStatus] = useState("idle"); // idle | checking | ok | error
  const [monitorLastCheck, setMonitorLastCheck] = useState(null);
  const [editingTrade, setEditingTrade] = useState(null);
  const [newsEvents, setNewsEvents] = useState(DEFAULT_NEWS_EVENTS);
  const [newsAlert, setNewsAlert] = useState(null); // { event, stage }

  useEffect(() => {
    (async () => {
      try {
        const s = await window.storage.get("gt_settings_v2", false);
        if (s) setSettings({ ...DEFAULT_SETTINGS, ...JSON.parse(s.value) });
      } catch (e) {}
      try {
        const r = await window.storage.get("gt_risk_v2", false);
        if (r) setRiskLimits({ ...DEFAULT_RISK, ...JSON.parse(r.value) });
      } catch (e) {}
      try {
        const p = await window.storage.get("gt_profile_v2", false);
        if (p) setProfile({ ...DEFAULT_PROFILE, ...JSON.parse(p.value) });
      } catch (e) {}
      try {
        const t = await window.storage.get("gt_trades_v2", false);
        if (t) setTrades(JSON.parse(t.value));
      } catch (e) {}
      try {
        const n = await window.storage.get("gt_news_v2", false);
        if (n) {
          const parsed = JSON.parse(n.value);
          setNewsEvents(parsed.length ? parsed : DEFAULT_NEWS_EVENTS);
        } else {
          // First run: seed with the curated default calendar and persist it.
          await window.storage.set("gt_news_v2", JSON.stringify(DEFAULT_NEWS_EVENTS), false);
        }
      } catch (e) {}
      setLoaded(true);
    })();
  }, []);

  const saveSettings = async (next) => {
    setSettings(next);
    try {
      await window.storage.set("gt_settings_v2", JSON.stringify(next), false);
    } catch (e) {}
  };
  const saveRisk = async (next) => {
    setRiskLimits(next);
    try {
      await window.storage.set("gt_risk_v2", JSON.stringify(next), false);
    } catch (e) {}
  };
  const saveProfile = async (next) => {
    setProfile(next);
    try {
      await window.storage.set("gt_profile_v2", JSON.stringify(next), false);
    } catch (e) {}
  };
  const saveTrades = async (next) => {
    setTrades(next);
    try {
      await window.storage.set("gt_trades_v2", JSON.stringify(next), false);
    } catch (e) {}
  };
  const saveNews = async (next) => {
    setNewsEvents(next);
    try {
      await window.storage.set("gt_news_v2", JSON.stringify(next), false);
    } catch (e) {}
  };

  const m = useMemo(() => computeMetrics(trades, settings), [trades, settings]);

  useEffect(() => {
    if (resultPopup) notifyResult(resultPopup.result, settings.soundEnabled !== false);
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [resultPopup]);

  const handleAddTrade = (form) => {
    const riskAmount = calcRiskAmount(form.entryPrice, form.stopLoss, form.lot, form.pointValue);
    const riskPercent = m.currentBalance ? (riskAmount / m.currentBalance) * 100 : 0;
    const trade = {
      id: uid(),
      symbol: form.symbol,
      direction: form.direction,
      entryPrice: Number(form.entryPrice),
      exitPrice: null,
      stopLoss: form.stopLoss ? Number(form.stopLoss) : null,
      takeProfit: form.takeProfit ? Number(form.takeProfit) : null,
      lot: Number(form.lot),
      pointValue: Number(form.pointValue) || 1,
      entryDate: form.entryDate,
      entryTime: form.entryTime,
      exitDate: null,
      exitTime: null,
      timeframe: form.timeframe,
      session: form.session,
      strategy: form.strategy,
      entryReason: form.entryReason,
      marketCondition: form.marketCondition,
      confidence: form.confidence,
      mistake: "",
      lesson: "",
      whatHappened: "",
      followedPlan: true,
      disciplineScore: null,
      screenshotEntry: form.screenshotEntry,
      screenshotResult: null,
      status: "Open",
      result: null,
      pnl: 0,
      rMultiple: null,
      riskAmount,
      riskPercent,
      balanceBefore: m.currentBalance,
      balanceAfter: null,
      createdAt: new Date().toISOString(),
    };
    saveTrades([trade, ...trades]);
  };

  const handleCloseTrade = (id, payload, reason) => {
    const t = trades.find((x) => x.id === id);
    if (!t) return;
    const balanceBefore = m.currentBalance;
    const pnl = calcPnL(t.direction, t.entryPrice, payload.exitPrice, t.lot, t.pointValue);
    const riskAmount = calcRiskAmount(t.entryPrice, t.stopLoss, t.lot, t.pointValue);
    const rMultiple = calcRMultiple(pnl, riskAmount);
    const result = calcResult(pnl);
    const updated = {
      ...t,
      exitPrice: payload.exitPrice,
      exitDate: new Date().toISOString(),
      exitTime: new Date().toTimeString().slice(0, 5),
      status: "Closed",
      result,
      pnl,
      rMultiple,
      whatHappened: payload.whatHappened,
      followedPlan: payload.followedPlan,
      mistake: payload.mistake,
      lesson: payload.lesson,
      disciplineScore: payload.disciplineScore,
      screenshotResult: payload.screenshotResult,
      balanceBefore,
      balanceAfter: balanceBefore + pnl,
    };
    const next = trades.map((x) => (x.id === id ? updated : x));
    saveTrades(next);
    setModalTrade(null);
    setResultPopup(updated);
    setResultReason(reason || null);
  };

  const handleSaveJournal = (id, notes) => {
    const next = trades.map((x) => (x.id === id ? { ...x, ...notes } : x));
    saveTrades(next);
  };

  const handleDeleteTrade = (id) => {
    saveTrades(trades.filter((t) => t.id !== id));
  };

  const handleUpdateTrade = (id, patch) => {
    const next = trades.map((t) => {
      if (t.id !== id) return t;
      const merged = { ...t, ...patch };
      const riskAmount = calcRiskAmount(merged.entryPrice, merged.stopLoss, merged.lot, merged.pointValue);
      const riskPercent = m.currentBalance ? (riskAmount / m.currentBalance) * 100 : 0;
      return { ...merged, riskAmount, riskPercent };
    });
    saveTrades(next);
  };

  const openModal = (trade) => {
    setModalTrade(trade);
    setModalMode(trade.status === "Open" ? "close" : "view");
  };
  const openCloseModal = (trade) => {
    setModalTrade(trade);
    setModalMode("close");
  };

  const handleQuickWin = (trade) => {
    if (!trade.takeProfit) return;
    handleCloseTrade(
      trade.id,
      { exitPrice: trade.takeProfit, whatHappened: "", followedPlan: true, mistake: "", lesson: "", disciplineScore: null, screenshotResult: null },
      "Ditutup manual di TP"
    );
  };
  const handleQuickLose = (trade) => {
    if (!trade.stopLoss) return;
    handleCloseTrade(
      trade.id,
      { exitPrice: trade.stopLoss, whatHappened: "", followedPlan: true, mistake: "", lesson: "", disciplineScore: null, screenshotResult: null },
      "Ditutup manual di SL"
    );
  };

  // Auto-monitor: polls live price for every open trade and auto-closes when
  // price reaches TP (Win) or SL (Loss), then shows a result popup.
  useEffect(() => {
    if (!monitorOn) return;
    const openTrades = trades.filter((t) => t.status === "Open" && (t.takeProfit || t.stopLoss));
    if (openTrades.length === 0) return;
    let cancelled = false;

    const checkAll = async () => {
      setMonitorStatus("checking");
      const symbols = [...new Set(openTrades.map((t) => t.symbol))];
      const prices = {};
      let anyOk = false;
      for (const sym of symbols) {
        try {
          const { price } = await fetchLivePrice(sym);
          if (price != null && !isNaN(price)) {
            prices[sym] = price;
            anyOk = true;
          }
        } catch (e) {}
      }
      if (cancelled) return;
      openTrades.forEach((t) => {
        const price = prices[t.symbol];
        if (price == null) return;
        const tp = t.takeProfit ? Number(t.takeProfit) : null;
        const sl = t.stopLoss ? Number(t.stopLoss) : null;
        if (t.direction === "Buy") {
          if (tp && price >= tp) {
            handleCloseTrade(
              t.id,
              { exitPrice: tp, whatHappened: "", followedPlan: true, mistake: "", lesson: "", disciplineScore: null, screenshotResult: null },
              "Auto-monitor · TP tercapai"
            );
          } else if (sl && price <= sl) {
            handleCloseTrade(
              t.id,
              { exitPrice: sl, whatHappened: "", followedPlan: true, mistake: "", lesson: "", disciplineScore: null, screenshotResult: null },
              "Auto-monitor · SL tersentuh"
            );
          }
        } else {
          if (tp && price <= tp) {
            handleCloseTrade(
              t.id,
              { exitPrice: tp, whatHappened: "", followedPlan: true, mistake: "", lesson: "", disciplineScore: null, screenshotResult: null },
              "Auto-monitor · TP tercapai"
            );
          } else if (sl && price >= sl) {
            handleCloseTrade(
              t.id,
              { exitPrice: sl, whatHappened: "", followedPlan: true, mistake: "", lesson: "", disciplineScore: null, screenshotResult: null },
              "Auto-monitor · SL tersentuh"
            );
          }
        }
      });
      setMonitorStatus(anyOk ? "ok" : "error");
      setMonitorLastCheck(new Date());
    };

    checkAll();
    const interval = setInterval(checkAll, 45000);
    return () => {
      cancelled = true;
      clearInterval(interval);
    };
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [monitorOn, trades]);

  // News-calendar watcher: fires a 5-minute warning and a live alert for each
  // high-impact event exactly once, with its own siren sound + vibration.
  useEffect(() => {
    const checkNews = () => {
      const now = Date.now();
      let changed = false;
      const next = newsEvents.map((e) => {
        const t = new Date(e.dateTime).getTime();
        const diffMin = (t - now) / 60000;
        if (!e.notifiedWarn && diffMin <= 5 && diffMin > -1) {
          changed = true;
          setNewsAlert({ event: e, stage: "warning" });
          playNewsAlarm();
          vibrateNews();
          return { ...e, notifiedWarn: true };
        }
        if (!e.notifiedLive && diffMin <= 0 && diffMin > -2) {
          changed = true;
          setNewsAlert({ event: e, stage: "live" });
          playNewsAlarm();
          vibrateNews();
          return { ...e, notifiedWarn: true, notifiedLive: true };
        }
        return e;
      });
      if (changed) saveNews(next);
    };
    checkNews();
    const interval = setInterval(checkNews, 20000);
    return () => clearInterval(interval);
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [newsEvents]);

  const handleExportJSON = () => {
    downloadFile(
      `gtrade-backup-${todayStr()}.json`,
      JSON.stringify({ settings, riskLimits, profile, trades }, null, 2),
      "application/json"
    );
  };
  const handleExportCSV = () => {
    downloadFile(`gtrade-trades-${todayStr()}.csv`, tradesToCSV(trades), "text/csv");
  };
  const handleImportJSON = (file) => {
    const reader = new FileReader();
    reader.onload = (e) => {
      try {
        const data = JSON.parse(e.target.result);
        if (data.settings) saveSettings({ ...DEFAULT_SETTINGS, ...data.settings });
        if (data.riskLimits) saveRisk({ ...DEFAULT_RISK, ...data.riskLimits });
        if (data.profile) saveProfile({ ...DEFAULT_PROFILE, ...data.profile });
        if (data.trades) saveTrades(data.trades);
      } catch (err) {}
    };
    reader.readAsText(file);
  };

  const handleResetAll = () => {
    saveTrades([]);
    saveSettings(DEFAULT_SETTINGS);
    saveRisk(DEFAULT_RISK);
    setModalTrade(null);
    setResultPopup(null);
    setShowResetConfirm(false);
  };

  if (!loaded) {
    return (
      <div style={{ background: COLORS.bg, minHeight: "100vh", display: "flex", alignItems: "center", justifyContent: "center", color: COLORS.textDim, fontFamily: "'Inter', sans-serif" }}>
        <style>{FONT_IMPORT}</style>
        Memuat Gtrade…
      </div>
    );
  }

  return (
    <div style={{ background: COLORS.bg, minHeight: "100vh", fontFamily: "'Inter', sans-serif", fontWeight: 700, color: COLORS.text, position: "relative" }}>
      <style>{FONT_IMPORT}</style>

      {/* Centered transparent watermark — sits behind all content, doesn't intercept clicks */}
      <div
        aria-hidden="true"
        style={{
          position: "fixed",
          inset: 0,
          display: "flex",
          alignItems: "center",
          justifyContent: "center",
          pointerEvents: "none",
          zIndex: -1,
          overflow: "hidden",
        }}
      >
        <img
          src={LOGO_WATERMARK}
          alt=""
          style={{
            width: "min(70vw, 480px)",
            height: "min(70vw, 480px)",
            objectFit: "cover",
            borderRadius: "50%",
            opacity: 0.07,
            filter: "grayscale(35%)",
          }}
        />
      </div>

      {/* Header */}
      <div
        style={{
          borderBottom: `1px solid ${COLORS.border}`,
          padding: "14px 20px",
          background: `linear-gradient(90deg, rgba(232,185,63,0.10), rgba(78,161,255,0.08), rgba(181,123,255,0.08))`,
        }}
      >
        <div style={{ maxWidth: 1100, margin: "0 auto", display: "flex", alignItems: "center", justifyContent: "space-between", flexWrap: "wrap", gap: 10 }}>
          <div style={{ display: "flex", alignItems: "center", gap: 10 }}>
            <div
              style={{
                width: 32,
                height: 32,
                borderRadius: 8,
                background: `linear-gradient(135deg, ${COLORS.gold}, ${COLORS.goldBright})`,
                display: "flex",
                alignItems: "center",
                justifyContent: "center",
                fontFamily: "'Times New Roman', Times, serif",
                fontWeight: 700,
                color: "#14171B",
                fontSize: 16,
              }}
            >
              G
            </div>
            <span style={{ fontFamily: "'Times New Roman', Times, serif", fontWeight: 700, fontSize: 19 }}>Gtrade</span>
          </div>
          <div style={{ display: "flex", alignItems: "center", gap: 8 }}>
            <img src={profile.photo} alt="" style={{ width: 28, height: 28, borderRadius: "50%", border: `1.5px solid ${COLORS.gold}`, objectFit: "cover" }} />
            <span style={{ fontSize: 12.5, color: COLORS.textDim }}>{profile.name}</span>
            <span style={{ fontSize: 10.5, color: COLORS.textFaint, background: COLORS.surfaceAlt, padding: "3px 8px", borderRadius: 20 }}>
              {profile.accountType} · {profile.accountTier}
            </span>
          </div>
        </div>
      </div>

      <Navigation active={activeTab} onChange={setActiveTab} />

      <div style={{ maxWidth: 1100, margin: "0 auto", padding: "20px 20px 90px" }}>
        {activeTab === "dashboard" && (
          <Dashboard
            trades={trades}
            settings={settings}
            riskLimits={riskLimits}
            chartRange={chartRange}
            setChartRange={setChartRange}
            onGoJournal={() => setActiveTab("journal")}
          />
        )}
        {activeTab === "journal" && (
          <JournalPage
            trades={trades}
            settings={settings}
            riskLimits={riskLimits}
            currentBalance={m.currentBalance}
            onSubmit={handleAddTrade}
            onOpen={openModal}
            onClose={openCloseModal}
            onDelete={handleDeleteTrade}
            onQuickWin={handleQuickWin}
            onQuickLose={handleQuickLose}
            onEdit={setEditingTrade}
            monitorOn={monitorOn}
            monitorStatus={monitorStatus}
            monitorLastCheck={monitorLastCheck}
            onToggleMonitor={() => setMonitorOn((v) => !v)}
          />
        )}
        {activeTab === "calendar" && (
          <CalendarPerformance trades={trades} currency={settings.currency} newsEvents={newsEvents} onChangeNews={saveNews} />
        )}
        {activeTab === "analytics" && <AnalyticsPage trades={trades} settings={settings} />}
        {activeTab === "settings" && (
          <SettingsPage
            settings={settings}
            onChangeSettings={saveSettings}
            riskLimits={riskLimits}
            onChangeRisk={saveRisk}
            profile={profile}
            onChangeProfile={saveProfile}
            onExportJSON={handleExportJSON}
            onExportCSV={handleExportCSV}
            onImportJSON={handleImportJSON}
            onRequestReset={() => setShowResetConfirm(true)}
          />
        )}
      </div>

      {modalTrade && (
        <TradeModal
          trade={modalTrade}
          currency={settings.currency}
          mode={modalMode}
          onClose={() => setModalTrade(null)}
          onCloseTrade={handleCloseTrade}
          onSaveJournal={handleSaveJournal}
        />
      )}

      {editingTrade && (
        <EditTradeModal trade={editingTrade} onClose={() => setEditingTrade(null)} onSave={handleUpdateTrade} />
      )}

      {resultPopup && (
        <ResultPopup
          trade={resultPopup}
          currency={settings.currency}
          reason={resultReason}
          onClose={() => {
            setResultPopup(null);
            setResultReason(null);
          }}
        />
      )}

      {showResetConfirm && (
        <ResetConfirmModal onCancel={() => setShowResetConfirm(false)} onConfirm={handleResetAll} />
      )}

      {newsAlert && (
        <NewsAlertModal event={newsAlert.event} stage={newsAlert.stage} onClose={() => setNewsAlert(null)} />
      )}

      <style>{`
        @keyframes gtZoomIn {
          from { transform: scale(0.75); opacity: 0; }
          to { transform: scale(1); opacity: 1; }
        }
        @keyframes gtPulse {
          0%, 100% { opacity: 1; }
          50% { opacity: 0.3; }
        }
        @keyframes gtRedPulse {
          0%, 100% { box-shadow: 0 24px 70px rgba(255,77,94,0.35); }
          50% { box-shadow: 0 24px 90px rgba(255,77,94,0.65); }
        }
        @keyframes gtFadeInUp {
          from { opacity: 0; transform: translateY(8px); }
          to { opacity: 1; transform: translateY(0); }
        }
        .gt-fade-in {
          animation: gtFadeInUp 0.32s ease both;
        }
        .gt-fade-in > * {
          animation: gtFadeInUp 0.4s ease both;
        }
        .gt-fade-in-card {
          animation: gtFadeInUp 0.28s ease both;
        }
        .gt-fade-in-card:active {
          border-color: ${COLORS.gold} !important;
        }
        @keyframes gtPopIn {
          0% { opacity: 0; transform: scale(0.6); }
          60% { opacity: 1; transform: scale(1.12); }
          100% { opacity: 1; transform: scale(1); }
        }
        .gt-pop-in {
          animation: gtPopIn 0.35s cubic-bezier(0.2, 0.9, 0.3, 1.3) both;
        }
        @media (max-width: 860px) {
          .gt-desktop-nav { display: none !important; }
          .gt-mobile-nav { display: flex !important; }
        }
        @media (min-width: 861px) {
          .gt-mobile-nav { display: none !important; }
        }
        @media (max-width: 720px) {
          div[style*="grid-template-columns: 340px 1fr"] {
            grid-template-columns: 1fr !important;
          }
        }
      `}</style>
    </div>
  );
}
